import {useState} from 'react';
import {
  Sun, CloudSun, Cloud, CloudRain, CloudSnow, CloudLightning, CloudFog,
  Wind, Droplets, RefreshCw,
} from 'lucide-react';
import { generateForecast } from '../../sites/weather-outlook';

const CONDITIONS = [
  { key: 'clear', label: 'Klar', Icon: Sun, color: 'var(--warm)' },
  { key: 'partly', label: 'Leicht bewölkt', Icon: CloudSun, color: 'var(--warm)' },
  { key: 'cloudy', label: 'Bewölkt', Icon: Cloud, color: 'var(--text-dim)' },
  { key: 'rain', label: 'Regen', Icon: CloudRain, color: 'var(--cool)' },
  { key: 'storm', label: 'Gewitter', Icon: CloudLightning, color: 'var(--alert)' },
  { key: 'snow', label: 'Schnee', Icon: CloudSnow, color: 'var(--cool)' },
  { key: 'fog', label: 'Nebel', Icon: CloudFog, color: 'var(--text-dim)' },
];

const WEEKDAYS = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];



export default function WeatherHeader({generateForecast}) {
    const [days, setDays] = useState(() => generateForecast(6));
    const [updatedAt, setUpdatedAt] = useState(new Date());
    const [spinning, setSpinning] = useState(false);

    const refresh = () => {
    setSpinning(true);
    //make an api call to update the weather by replacing 'generateForecast' method with an api call
    setDays(generateForecast(6));
    setUpdatedAt(new Date());
    setTimeout(() => setSpinning(false), 600);
  };

    return (
        <header className="wx-header">
        <div>
          <div className="wx-eyebrow">Wetterprognose</div>
          <div className="wx-title">Nächste Tage</div>
        </div>
        <button className={`wx-refresh ${spinning ? 'spin' : ''}`} onClick={refresh}>
          <RefreshCw size={12} strokeWidth={2} />
          <span className="wx-mono">{updatedAt.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })}</span>
        </button>
      </header>
    )
}
